-- 📚 꼭집 주거 사전 — 공공임대 유형별 정의 · 공통
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.4초 · 결과:
-- {"dd": 9, "js": 1, "hb": 12, "law": 148, "law_def": 0, "ex": ["2015122300020873", "2015122300020843", "2015122300020835"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('dd',(select count(distinct announcement_id) from y where '1'='1' and t~'든든전세주택은[^.]{0,40}순수\s*전세'),'js',(select count(distinct announcement_id) from y where t~'전세임대(주택)?은[^.]{0,30}(LH|공사)\s*소유\s*주택이\s*아닌'),'hb',(select count(distinct announcement_id) from y where t~'행복주택은[^.]{0,30}최대\s*거주기간'),'law',(select count(distinct announcement_id) from y where t~'공공주택\s*특별법'),'law_def',(select count(distinct announcement_id) from y where t~'공공주택\s*특별법\s*시행령\s*제\s*2\s*조'),'ex',(select json_agg(i) from(select distinct announcement_id i from y where t~'든든전세주택은[^.]{0,40}순수\s*전세' order by 1 desc limit 3)q))j;
